const explanations={make:'Marca del fabricante. Elígela para cargar modelos disponibles.',year:'Año modelo de la unidad, según sus documentos.',name:'Modelo de esa marca y año. No es el acabado o versión.',version:'Selecciona la configuración que coincide con tu unidad. Los datos técnicos pertenecen a ese mismo registro.',engine:'Cilindrada, cilindros y sistema de propulsión de la versión elegida.',fuel:'Combustible o sistema de propulsión confirmado por la configuración.',transmission:'Tipo de caja de la unidad. No cambia el motor seleccionado.',drive:'4x2, 4x4 o AWD, según la configuración exacta.',type:'Tipo de carrocería: SUV, sedán, camioneta, etc.',mileage:'Kilometraje real que indica el vehículo. Escribe también la unidad si corresponde.',condition:'Estado comercial de la unidad: nueva, seminueva o usada.',color:'Color real de esta unidad. Puedes escribirlo libremente.',city:'Ciudad boliviana donde se encuentra el vehículo.',country:'Por ahora el mercado está limitado a Bolivia.',price:'Precio anunciado al público. No es necesariamente el precio final de venta.',currency:'Moneda del precio público. No obliga a cobrar tu comisión en esa moneda.',status:'Disponible se muestra al cliente; borrador y vendido quedan ocultos.',description:'Información pública del vehículo. Evita incluir el mínimo autorizado o acuerdos privados.',featured:'Puedes seleccionar hasta cinco vehículos disponibles para la ruleta.',ownerName:'Nombre privado del propietario o cliente que te entregó el vehículo.',minSalePrice:'Mínimo que autorizó el propietario para el precio total de venta; no se muestra al comprador.',mode:'Porcentaje sobre la venta real, monto fijo o excedente sobre lo que recibe el propietario.',rate:'Porcentaje acordado sobre el precio final negociado, no sobre el precio anunciado.',fixedCommission:'Monto fijo de comisión, expresado en la moneda de la venta privada.',ownerTarget:'Importe que debe recibir el propietario. La diferencia respecto de la venta es tu comisión.',salePrice:'Precio total realmente negociado con el comprador. Cambia la comisión porcentual.',saleDate:'Fecha del cierre. El cierre suma a tus resultados al guardar como vendido.',costs:'Gastos tuyos, en la moneda de la venta, que se descuentan de la comisión bruta.',received:'Total de comisión que ya recibiste, en la moneda de cobro. Si hubo varios pagos usa el cambio efectivo promedio.',payoutCurrency:'Moneda en la que cobrarás la comisión; puede ser distinta de la moneda del vehículo.',exchangeRate:'Cambio acordado como base de comparación: cuántos Bs equivale US$ 1. No se actualiza automáticamente.',receivedRate:'Cambio realmente aplicado a tu cobro: Bs por US$ 1. Permite medir el valor equivalente y la diferencia cambiaria. Para varios pagos usa total Bs dividido por total USD cancelados.',notes:'Detalles internos del acuerdo. Solo aparecen en administración y exportación privada.',belowMinimumApproval:'Si vendes bajo el mínimo, registra la autorización adicional del propietario.',offerEnabled:'Actívalo al bajar un precio ya guardado. El cliente verá el precio anterior y el nuevo; desactívalo para quitar la oferta.'};
export function installHelp(root=document){
 let bubble=document.querySelector('#admin-help-tooltip');if(!bubble){bubble=document.createElement('div');bubble.id='admin-help-tooltip';bubble.className='admin-help-tooltip';bubble.role='tooltip';bubble.hidden=true;document.body.append(bubble);}
 for(const input of root.querySelectorAll('input,select,textarea')){const key=(input.id||'').startsWith('finance-')?input.id.slice(8):input.name||input.id;if(!explanations[key]||input.closest('label')?.querySelector('.field-help'))continue;const label=input.closest('label');if(!label)continue;const originalLabel=input.getAttribute('aria-label')||label.firstChild?.textContent?.trim()||label.textContent.trim()||key;if(!input.getAttribute('aria-label'))input.setAttribute('aria-label',originalLabel);const help=document.createElement('button');help.type='button';help.className='field-help';help.textContent='?';help.setAttribute('aria-label','Ayuda: '+originalLabel);help.setAttribute('aria-describedby',bubble.id);const show=()=>{bubble.textContent=explanations[key];bubble.hidden=false;const r=help.getBoundingClientRect(),w=Math.min(310,innerWidth-32);bubble.style.width=w+'px';bubble.style.left=Math.max(16,Math.min(r.left,innerWidth-w-16))+'px';const h=bubble.getBoundingClientRect().height;bubble.style.top=(r.bottom+h+20<innerHeight?r.bottom+9:Math.max(8,r.top-h-9))+'px';};help.onmouseenter=show;help.onfocus=show;help.onmouseleave=()=>{bubble.hidden=true;};help.onblur=()=>{bubble.hidden=true;};help.onclick=e=>{e.preventDefault();e.stopPropagation();show();};label.append(help);}
 document.addEventListener('pointerdown',e=>{if(!e.target.closest('.field-help'))bubble.hidden=true;});document.addEventListener('keydown',e=>{if(e.key==='Escape')bubble.hidden=true;});window.addEventListener('scroll',()=>{bubble.hidden=true;},{passive:true});
}
